import json
from pathlib import Path
from typing import List, Dict, Any, TextIO


def _read_lines(path: Path) -> List[str]:
    """Read file content, preserving line boundaries."""
    try:
        return path.read_text(encoding="utf-8").splitlines(keepends=True)
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {path}") from None
    except IsADirectoryError:
        raise IsADirectoryError(f"Path is a directory, not a file: {path}") from None
    except PermissionError:
        raise PermissionError(f"Permission denied reading: {path}") from None
    except UnicodeDecodeError as e:
        raise ValueError(f"Unable to decode file as UTF-8: {path}") from e


